it('registers through its service provider and merges its config', function () {
    TestApp::boot();
    expect(config('connectors.stripe.mode'))->toBe('auto');
    expect(config('connectors.stripe.credentials'))->toBeArray();
});

it('fakes customer_create and records it for assertSent', function () {
    TestApp::boot();
    Stripe::fake();
    $config = [
        'email' => '  Example-email  ',
        'name' => 'example-name',
        'phone' => 'example-phone',
        'metadata' => [
            'order_id' => '7',
        ],
    ];
    $result = Stripe::call('customer_create', $config, idempotencyKey: 'test-key');

    expect($result->mode->value)->toBe('fake');
    Stripe::assertSent('customer_create', fn (array $sent): bool => $sent == $config);
    Stripe::assertNotSent('no_such_operation');
    Stripe::assertSentCount(1);
});

it('refuses a forged webhook delivery before the app sees it', function () {
    $app = TestApp::boot();
    $app['router']->stripeWebhook('/hooks/stripe');
    $response = TestApp::dispatch($app, Request::create('/hooks/stripe', 'POST', server: ['CONTENT_TYPE' => 'application/json'], content: '{"forged":true}'));

    expect($response->getStatusCode())->toBe(401);
});
